draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  for (let i = 0; i < 50; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * W, -Math.random() * H + Math.sin(t + i) * H);
    ctx.lineTo(Math.random() * W, Math.sin(t + i) * H + H / 2);
    ctx.stroke();
  }
  ctx.restore();
}
